package app.marketlens;
import android.content.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.*;
import java.time.format.*;
import java.util.*;
import java.util.regex.*;
import org.json.*;

final class Repository {
 static final String NSE="https://www.nseindia.com",AMC="https://amc.ppfas.com",PPFAS=AMC+"/downloads/portfolio-disclosure/",AMFI="https://www.amfiindia.com/online-center/portfolio-disclosure";
 final Net net;private final File fundsFile;final Map<String,Data.Stock> stocks=new LinkedHashMap<>();private final List<Data.Portfolio> funds=new ArrayList<>();String storageIssue="";
 Repository(Context c)throws Exception{net=new Net(new File(c.getFilesDir(),"sources"));fundsFile=new File(c.getFilesDir(),"portfolios.json");try(InputStream in=c.getAssets().open("equities.csv")){for(Data.Stock s:Parse.catalog(new String(Net.read(in,2*1024*1024),StandardCharsets.UTF_8)))stocks.put(s.symbol,s);}if(fundsFile.exists())try{JSONArray a=new JSONArray(new String(Files.readAllBytes(fundsFile.toPath()),StandardCharsets.UTF_8));for(int i=0;i<a.length();i++)funds.add(Data.Portfolio.from(a.getJSONObject(i)));}catch(Exception e){storageIssue="Saved portfolios could not be read. The original file has been retained.";}}
 Data.Stock stock(String symbol){Data.Stock s=stocks.get(symbol);return s==null?new Data.Stock(symbol,symbol,""):s;}
 static String encoded(String s){try{return URLEncoder.encode(s,"UTF-8");}catch(Exception e){throw new IllegalArgumentException(e);}}
 static String quoteUrl(String symbol){return quoteUrl(symbol,"EQ");}
 static String quoteUrl(String symbol,String series){return NSE+"/api/NextApi/apiClient/GetQuoteApi?functionName=getSymbolData&marketType=N&series="+encoded(series)+"&symbol="+encoded(symbol);}
 private String series(String symbol){String s=stock(symbol).series;return s.matches("[A-Z0-9]{1,4}")?s:"EQ";}
 static String financialUrl(String symbol){return NSE+"/api/integrated-filing-results?index=equities&symbol="+encoded(symbol)+"&type=Integrated%20Filing-%20Financials&page=1&size=20";}
 static String ownershipUrl(String symbol){return NSE+"/api/corporate-share-holdings-master?index=equities&symbol="+encoded(symbol);}
 Data.Screen screen(boolean high,boolean force)throws Exception{Net.Result r=net.get(NSE+"/api/live-analysis-52Week?index="+(high?"high":"low"),120000,force);Data.Screen s=Parse.screen(r.text());for(Data.Hit h:s.hits){Data.Stock directory=stocks.get(h.stock.symbol);if(directory!=null)h.stock=directory;}s.saved=r.saved;s.fetched=r.fetched;s.issue=r.issue;return s;}
 Data.Quote quote(String symbol,boolean force)throws Exception{Net.Result r=net.get(quoteUrl(symbol,series(symbol)),120000,force);Data.Quote q=Parse.quote(r.text(),symbol,series(symbol));q.saved=r.saved;q.fetched=r.fetched;q.issue=r.issue;Data.Stock s=stocks.get(symbol);if(s!=null&&!s.isin.isEmpty()&&!q.isin.isEmpty()&&!s.isin.equals(q.isin))q.issue="Exchange ISIN differs from the bundled directory; use the exchange ISIN for holdings.";return q;}
 Data.Quote peekQuote(String symbol){try{Net.Result r=net.peek(quoteUrl(symbol,series(symbol)));if(r==null)return null;Data.Quote q=Parse.quote(r.text(),symbol,series(symbol));q.saved=true;q.fetched=r.fetched;return q;}catch(Exception e){return null;}}
 Data.Financial financial(String symbol,boolean force)throws Exception{Net.Result list=net.get(financialUrl(symbol),86400000,force);JSONObject filing=Parse.latest(list.text(),symbol,true);Net.Result r=net.get(Parse.str(filing,"xbrl"),31536000000L,force);Data.Financial f=Parse.financial(r.bytes,filing);f.saved=list.saved||r.saved;f.fetched=Math.min(list.fetched,r.fetched);f.issue=!list.issue.isEmpty()?list.issue:r.issue;
 for(boolean yearAgo:new boolean[]{false,true})try{JSONObject prior=Comparisons.filing(list.text(),symbol,true,f.end,f.basis,yearAgo);if(prior!=null){Net.Result document=net.get(Parse.str(prior,"xbrl"),31536000000L,false);Data.Financial comparison=Parse.financial(document.bytes,prior);if(Comparisons.fits(f,comparison)){if(yearAgo)f.yearAgo=comparison;else f.previous=comparison;}}}catch(Exception ignored){}return f;}
 Data.Ownership ownership(String symbol,boolean force)throws Exception{Net.Result list=net.get(ownershipUrl(symbol),86400000,force);JSONObject filing=Parse.latest(list.text(),symbol,false);Net.Result r=net.get(Parse.str(filing,"xbrl"),31536000000L,force);Data.Ownership o=Parse.ownership(r.bytes,filing);o.saved=list.saved||r.saved;o.fetched=Math.min(list.fetched,r.fetched);o.issue=!list.issue.isEmpty()?list.issue:r.issue;
 try{JSONObject prior=Comparisons.filing(list.text(),symbol,false,o.date,"",false);if(prior!=null){Net.Result document=net.get(Parse.str(prior,"xbrl"),31536000000L,false);o.previous=Parse.ownership(document.bytes,prior);}}catch(Exception ignored){}return o;}
 synchronized List<Data.Portfolio> portfolios(){return new ArrayList<>(funds);}
 synchronized List<Data.Holding> holdings(String isin){List<Data.Holding> out=new ArrayList<>();if(!Data.isin(isin))return out;for(Data.Portfolio p:funds)for(Data.Holding h:p.holdings)if(isin.equals(h.isin))out.add(h);out.sort((a,b)->Double.compare(b.weight,a.weight));return out;}
 synchronized void add(List<Data.Portfolio> incoming)throws Exception{List<Data.Portfolio> merged=new ArrayList<>(funds);for(Data.Portfolio p:incoming){if(p.holdings.isEmpty()||Parse.canonical(p.date).isEmpty())throw new IOException("Portfolio is empty or undated");if(LocalDate.parse(p.date).isAfter(LocalDate.now(ZoneId.of("Asia/Kolkata")).plusDays(1)))throw new IOException("Portfolio reporting date is in the future");Data.Portfolio old=null;for(Data.Portfolio candidate:merged)if(candidate.id.equals(p.id))old=candidate;if(old!=null&&old.date.compareTo(p.date)>0)throw new IOException("An older disclosure cannot replace the newer saved snapshot");if(old!=null)merged.remove(old);merged.add(p);}JSONArray a=new JSONArray();for(Data.Portfolio p:merged)a.put(p.json());File temp=new File(fundsFile.getParentFile(),"portfolios.tmp");Files.write(temp.toPath(),a.toString().getBytes(StandardCharsets.UTF_8));Files.move(temp.toPath(),fundsFile.toPath(),StandardCopyOption.REPLACE_EXISTING);funds.clear();funds.addAll(merged);storageIssue="";}
 synchronized void remove(String id)throws Exception{List<Data.Portfolio> keep=new ArrayList<>();for(Data.Portfolio p:funds)if(!p.id.equals(id))keep.add(p);JSONArray a=new JSONArray();for(Data.Portfolio p:keep)a.put(p.json());File temp=new File(fundsFile.getParentFile(),"portfolios.tmp");Files.write(temp.toPath(),a.toString().getBytes(StandardCharsets.UTF_8));Files.move(temp.toPath(),fundsFile.toPath(),StandardCopyOption.REPLACE_EXISTING);funds.clear();funds.addAll(keep);}
 interface Progress {void update(String message);}
 String syncFunds(Progress progress)throws Exception{Net.Result page=net.get(PPFAS,86400000,true);Map<String,String[]> links=fundLinks(page.text());if(links.isEmpty())throw new IOException("No supported .xlsx disclosures found on the AMC page");int done=0;List<String> failures=new ArrayList<>();for(Map.Entry<String,String[]> entry:links.entrySet()){String id=entry.getKey(),url=entry.getValue()[0],date=entry.getValue()[1];progress.update("Reading "+id+" · "+date);try{Net.Result r=net.get(url,86400000,false);List<Data.Portfolio> parsed=Xlsx.portfolios(r.bytes,"",date,url);if(parsed.size()!=1)throw new IOException("Expected one scheme per workbook");Data.Portfolio p=parsed.get(0);p.id="ppfas:"+id;p.imported=false;p.saved=r.saved;p.fetched=r.fetched;p.issue=r.issue;add(Collections.singletonList(p));done++;}catch(Exception e){failures.add(id+": "+Net.message(e));}}String message="Updated "+done+" / "+links.size()+" PPFAS scheme disclosures. Coverage excludes other AMCs unless imported.";if(!failures.isEmpty())message+="\n"+String.join("\n",failures);return message;}
 static Map<String,String[]> fundLinks(String html){Map<String,String[]> out=new LinkedHashMap<>();Matcher m=Pattern.compile("href=[\"']([^\"']+\\.xlsx(?:\\?[^\"']*)?)[\"']",Pattern.CASE_INSENSITIVE).matcher(html);while(m.find()){String path=m.group(1).replace("&amp;","&");Matcher f=Pattern.compile("(PPFCF|PPTSF|PPCHF|PPAF|PPDAAF|PPLCF)_PPFAS_Monthly_Portfolio_Report_([A-Za-z]+)_(\\d{1,2})_(\\d{4})",Pattern.CASE_INSENSITIVE).matcher(path);if(!f.find())continue;String id=f.group(1).toUpperCase(Locale.ROOT),date="";try{date=LocalDate.parse(f.group(2)+" "+f.group(3)+" "+f.group(4),DateTimeFormatter.ofPattern("MMMM d uuuu",Locale.ENGLISH)).toString();}catch(Exception ignored){continue;}try{String url=new URI(AMC+"/").resolve(path).toString();if(!Net.allowed(url)||!"amc.ppfas.com".equals(new URI(url).getHost()))continue;String[] old=out.get(id);if(old==null||date.compareTo(old[1])>0)out.put(id,new String[]{url,date});}catch(Exception ignored){}}return out;}
}
